const words = ["0", "", "no", "false"];
console.log(words.filter(Boolean).length);

const lengths = words.map((word) => word.length);
console.log(lengths.join(","));
console.log(lengths.filter((n, i) => n > i).join(","));

let seen = 0;
const out = words.forEach(() => seen++);
console.log(seen, out);
